// Branch-specific logos embedded as base64 for jsPDF/print/WhatsApp contexts
// that can't load /public files directly (e.g. jsPDF.addImage, or emails/exports
// rendered outside the app's own origin). Regenerate from public/yg-logo-pos*.png
// if those source logos ever change.
export const LOGO_BASE64_POS1 = 'data:image/png;base64,'

export const LOGO_BASE64_POS2 = 'data:image/png;base64,'

// Christmas POS (POS 3): wide (3:2) logo, so PDFs must fit it by aspect ratio instead of stretching it square.
export const LOGO_BASE64_POS3 = 'data:image/png;base64,'
export const LOGO_BASE64_POS3_ASPECT = 1.5000

/** @deprecated use LOGO_BASE64_POS1 / LOGO_BASE64_POS2 directly (kept for any
 * call site that hasn't been made branch-aware yet). */
export const LOGO_BASE64 = LOGO_BASE64_POS1
